class Solution {
    public boolean isValidSudoku(char[][] board) {
        for (int r = 0; r < 9; r++) {
            Set<Character> seen = new HashSet<>();
            for (int c = 0; c < 9; c++) {
                char val = board[r][c];
                if (val != '.') {
                    if (seen.contains(val)) {
                        return false;
                    }
                    seen.add(val);
                }
            }
        }

        for (int c = 0; c < 9; c++) {
            Set<Character> seen = new HashSet<>();
            for (int r = 0; r < 9; r++) {
                char val = board[r][c];
                if (val != '.') {
                    if (seen.contains(val)) {
                        return false;
                    }
                    seen.add(val);
                }
            }
        }

        for (int boxR = 0; boxR < 9; boxR += 3) {
            for (int boxC = 0; boxC < 9; boxC += 3) {
                Set<Character> seen = new HashSet<>();
                for (int r = boxR; r < boxR + 3; r++) {
                    for (int c = boxC; c < boxC + 3; c++) {
                        char val = board[r][c];
                        if (val != '.') {
                            if (seen.contains(val)) {
                                return false;
                            }
                            seen.add(val);
                        }
                    }
                }
            }
        }
        return true;
    }
