using namespace std;

class Solution {
    public:
    int lengthOfLongestSubstring(string s) {
        unordered_set<char> set;
        int left = 0, maxLen = 0;
        for (int right = 0; right < (int)s.size(); right++) {
            while (set.count(s[right])) {
                set.erase(s[left]);
                left++;
            }
            set.insert(s[right]);
