import java.util.HashMap;
import java.util.Map;

class Solution {
    public String minWindow(String s, String t) {
        if (s == null || t == null || s.length() < t.length()) {
            return "";
        }
        Map<Character, Integer> tCounts = new HashMap<>();
        for (char c : t.toCharArray()) {
            tCounts.put(c, tCounts.getOrDefault(c, 0) + 1);
        }
        int required = tCounts.size();
        int minLen = Integer.MAX_VALUE;
        String bestStr = "";

        for (int i = 0; i < s.length(); i++) {
            Map<Character, Integer> curr = new HashMap<>();
            int matched = 0;
            for (int j = i; j < s.length(); j++) {
                char c = s.charAt(j);
                if (tCounts.containsKey(c)) {
                    curr.put(c, curr.getOrDefault(c, 0) + 1);
                    if (curr.get(c).intValue() == tCounts.get(c).intValue()) {
                        matched++;
                    }
                }
                if (matched == required) {
                    int len = j - i + 1;
                    if (len < minLen) {
                        minLen = len;
                        bestStr = s.substring(i, j + 1);
                    }
                    break;
                }
            }
        }
        return bestStr;
    }
}

