import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> res = new ArrayList<>();
        int k = p.length();
        int n = s.length();
        if (k > n) {
            return res;
        }
        char[] targetArr = p.toCharArray();
        Arrays.sort(targetArr);
        String target = new String(targetArr);

        for (int i = 0; i <= n - k; i++) {
            char[] subArr = s.substring(i, i + k).toCharArray();
            Arrays.sort(subArr);
            if (new String(subArr).equals(target)) {
                res.add(i);
            }
        }
        return res;
    }
}

