        i++) {
            int[] a=expand(s,i,i),b=expand(s,i,i+1);
            if(a[1]-a[0]>bestR-bestL) {
                bestL=a[0];
                bestR=a[1];
            }
            if(b[1]-b[0]>bestR-bestL) {
                bestL=b[0];
                bestR=b[1];
            }
