class Solution:
    def mergeKLists(self, lists: list) -> list:
        if not lists: return None
        def merge2(l1, l2):
            dummy = ListNode(0)
            tail = dummy
            while l1 and l2:
                if l1.val < l2.val:
                    tail.next, l1 = l1, l1.next
                else:
                    tail.next, l2 = l2, l2.next
                tail = tail.next
            tail.next = l1 or l2
            return dummy.next
        step = 1
        while step < len(lists):
            for i in range(0, len(lists) - step, step * 2):
                lists[i] = merge2(lists[i], lists[i + step])
            step *= 2
        return lists[0]

