import java.util.ArrayList;
import java.util.List;

class MinStack {
    private List<Integer> stack;

    public MinStack() {
        stack = new ArrayList<>();
    }

    public void push(int val) {
        stack.add(val);
    }

    public void pop() {
        if (!stack.isEmpty()) {
            stack.remove(stack.size() - 1);
        }
    }

    public int top() {
        return stack.get(stack.size() - 1);
    }

    public int getMin() {
        int minVal = stack.get(0);
        for (int x : stack) {
            if (x < minVal) {
                minVal = x;
            }
        }
        return minVal;
    }
}

