class Solution:
    def search(self, nums: list[int], target: int) -> int:
        def helper(l, r):
            if l > r: return -1
            mid = l + (r - l) // 2
            if nums[mid] == target: return mid
            elif nums[mid] > target: return helper(l, mid - 1)
            else: return helper(mid + 1, r)
        return helper(0, len(nums) - 1)

