        def get_level(node, target_level, current_level, acc):
            if not node:
                return
            if current_level == target_level:
                acc.append(node.val)
                return
            get_level(node.left, target_level, current_level + 1, acc)
            get_level(node.right, target_level, current_level + 1, acc)

