        curr = root
        while curr:
            path_p.append(curr)
            if p.val < curr.val:
                curr = curr.left
            elif p.val > curr.val:
                curr = curr.right
            else:
                break
        path_q = []
        curr = root
        while curr:
            path_q.append(curr)
            if q.val < curr.val:
                curr = curr.left
            elif q.val > curr.val:
                curr = curr.right
            else:
                break
        lca = root
        for a, b in zip(path_p, path_q):
            if a is b:
                lca = a
            else:
                break
        return lca

