import java.util.*;

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        List<TreeNode> pathP = new ArrayList<>();
        TreeNode curr = root;
        while (curr != null) {
            pathP.add(curr);
            if (p.val < curr.val) {
                curr = curr.left;
            }
            else if (p.val > curr.val) {
                curr = curr.right;
            }
            else {
                break;
            }
        }

        List<TreeNode> pathQ = new ArrayList<>();
        curr = root;
        while (curr != null) {
            pathQ.add(curr);
            if (q.val < curr.val) {
                curr = curr.left;
            }
            else if (q.val > curr.val) {
                curr = curr.right;
            }
            else {
                break;
            }
        }

        TreeNode lca = root;
        int minLen = Math.min(pathP.size(), pathQ.size());
        for (int i = 0; i < minLen; i++) {
            if (pathP.get(i) == pathQ.get(i)) {
                lca = pathP.get(i);
            }
            else {
                break;
            }
        }
        return lca;
    }
}

