class Solution:
    def numIslands(self, grid: list[list[str]]) -> int:
        if not grid:
            return 0
        R, C = len(grid), len(grid[0])
        visited = [[False] * C for _ in range(R)]
        islands = 0

        def dfs(r, c):
            if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] != '1' or visited[r][c]:
                return
            visited[r][c] = True
            dfs(r + 1, c)
            dfs(r - 1, c)
            dfs(r, c + 1)
            dfs(r, c - 1)

        for r in range(R):
            for c in range(C):
                if grid[r][c] == '1' and not visited[r][c]:
                    islands += 1
                    dfs(r, c)
        return islands

