import java.util.*;

class Solution {
    public int orangesRotting(int[][] grid) {
        int R = grid.length;
        int C = grid[0].length;
        int minutes = 0;
        int[][] dirs = {
            {
                -1, 0
            }
            , {
                1, 0
            }
            , {
                0, -1
            }
            , {
                0, 1
            }
        }
        ;

        while (true) {
            List<int[]> toRot = new ArrayList<>();
            for (int r = 0; r < R; r++) {
                for (int c = 0; c < C; c++) {
                    if (grid[r][c] == 1) {
                        for (int[] d : dirs) {
                            int nr = r + d[0];
                            int nc = c + d[1];
                            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == 2) {
                                toRot.add(new int[]{r, c});
                                break;
                            }
                        }
                    }
                }
            }
            if (toRot.isEmpty()) {
                break;
            }
            for (int[] cell : toRot) {
                grid[cell[0]][cell[1]] = 2;
            }
            minutes++;
        }

        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == 1) {
                    return -1;
                }
            }
        }
        return minutes;
    }
}

