import java.util.*;
class Solution {
    public int orangesRotting(int[][] g) {
        int m=g.length,n=g[0].length,f=0,min=0;
        Queue<int[]>q=new ArrayDeque<>();
        for(int i=0;i<m;i++)for(int j=0;j<n;j++) {
            if(g[i][j]==2)q.add(new int[] {
                i,j
            }
            );
            else if(g[i][j]==1)f++;
        }
        int[][]d= {
            {
                1,0
            }
            , {
                -1,0
            }
            , {
                0,1
            }
            , {
                0,-1
            }
        }
        ;
        while(!q.isEmpty()&&f>0) {
            int sz=q.size();
            while(sz-->0) {
                int[]x=q.poll();
                for(int[]z:d) {
                    int r=x[0]+z[0],c=x[1]+z[1];
                    if(r>=0&&r<m&&c>=0&&c<n&&g[r][c]==1) {
                        g[r][c]=2;
                        f--;
                        q.add(new int[] {
                            r,c
                        }
                        );
                    }
                }
            }
            min++;
        }
        return f==0?min:-1;
    }
}

