class Solution:
    def pacificAtlantic(self, heights: list[list[int]]) -> list[list[int]]:
        R, C = len(heights), len(heights[0])
        res = []
        for r in range(R):
            for c in range(C):
                visited = set()
                reach_p = [False]
                reach_a = [False]
                def dfs(cr, cc):
                    if cr == 0 or cc == 0:
                        reach_p[0] = True
                    if cr == R - 1 or cc == C - 1:
                        reach_a[0] = True
                    if reach_p[0] and reach_a[0]:
                        return
                    visited.add((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited:
                            if heights[nr][nc] <= heights[cr][cc]:
                                dfs(nr, nc)
                dfs(r, c)
                if reach_p[0] and reach_a[0]:
                    res.append([r, c])
        return res

