import java.util.*;
class Solution {
    public int networkDelayTime(int[][] times,int n,int k) {
        List<int[]>[]g=new List[n+1];
        for(int i=1;i<=n;i++)g[i]=new ArrayList<>();
        for(int[]e:times)g[e[0]].add(new int[] {
            e[1],e[2]
        }
        );
        int[]d=new int[n+1];
        Arrays.fill(d,Integer.MAX_VALUE);
        d[k]=0;
        PriorityQueue<int[]>q=new PriorityQueue<>(Comparator.comparingInt(a->a[0]));
        q.add(new int[] {
            0,k
        }
        );
        while(!q.isEmpty()) {
            int[]x=q.poll();
            if(x[0]!=d[x[1]])continue;
            for(int[]e:g[x[1]])if(x[0]+e[1]<d[e[0]]) {
                d[e[0]]=x[0]+e[1];
                q.add(new int[] {
                    d[e[0]],e[0]
                }
                );
            }
        }
        int ans=0;
        for(int i=1;i<=n;i++)if(d[i]==Integer.MAX_VALUE)return -1;
        else ans=Math.max(ans,d[i]);
        return ans;
    }
}

