        memo = {}
        def dfs(rem):
            if rem == 0: return 0
            if rem < 0: return -1
            if rem in memo: return memo[rem]
            min_cost = float('inf')
            for coin in coins:
                res = dfs(rem - coin)
                if res >= 0 and res < min_cost:
                    min_cost = res + 1
            memo[rem] = -1 if min_cost == float('inf') else min_cost
            return memo[rem]
        return dfs(amount)

