        if (rem < 0) return -1;
        if (memo[rem] != -2) return memo[rem];
        int minCoins = INT_MAX;
        for (int coin : coins) {
            int res = dfs(coins, rem - coin, memo);
            if (res >= 0 && res < minCoins) minCoins = res + 1;
