        return memo[rem] = (minCoins == INT_MAX) ? -1 : minCoins;
    }
    public:
    int coinChange(vector<int>& coins, int amount) {
        vector<int> memo(amount + 1, -2);
        return dfs(coins, amount, memo);
    }
