class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length(), n = word2.length();
        int[][] memo = new int[m][n];
        return dfs(word1, word2, 0, 0, memo);
    }
    private int dfs(String s1, String s2, int i, int j, int[][] memo) {
        if (i == s1.length()) return s2.length() - j;
        if (j == s2.length()) return s1.length() - i;
        if (memo[i][j] > 0) return memo[i][j];
        if (s1.charAt(i) == s2.charAt(j)) return memo[i][j] = dfs(s1, s2, i + 1, j + 1, memo);
        int ins = dfs(s1, s2, i, j + 1, memo);
        int del = dfs(s1, s2, i + 1, j, memo);
        int rep = dfs(s1, s2, i + 1, j + 1, memo);
        return memo[i][j] = 1 + Math.min(ins, Math.min(del, rep));
    }
}

