            res.push_back(path);
            return;
        }
        for (size_t i = 0; i < nums.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                path.push_back(nums[i]);
                backtrack(nums, used, path, res);
                path.pop_back();
                used[i] = false;
            }
        }
